-- ######################## M187-01 · Anwendungsbereich ########################
-- sonderanwendung
update public.fields set verification_status='verified_against_standard', verification_quote='In diesem Merkblatt werden folgende Ziele der Regenwasserbehandlung beschrieben, die über die im Arbeitsblatt DWA-A 178 beschriebene Standardanwendung hinausgehen: | langfristiger, stabiler P-Rückhalt, | langfristiger, stabiler Rückhalt von Spurenstoffen, | langfristiger, stabiler Rückhalt von Mikroorganismen, | Behandlung von niederschlagsbedingten Abflüssen mit hoher organischer Belastung, | dezentrale Klein-Retentionsbodenfilterbecken. — printed p.9', verification_note='md-verified 2026-09-05 (§1, printed p.9) [VC]', verified_at=now() where id='e9d7ab3e-ef7e-40c2-ac02-bc940f4582ce' and verification_status not in ('verified_against_standard','corrected');

