-- attest_m187_04_req_07
update public.fields set verification_status='verified_against_standard', verification_quote='Unabhängig von den Verfahrensanpassungen zur Erreichung einer spezifischen Zielsetzung sind einige Grundlagen essenziell, um einen langfristigen Betrieb der Anlagen sicherzustellen: | Beschickung mit ausreichend langen Trockenphasen, | aerobe Betriebsbedingungen, | geringe, kontrollierbare Filtergeschwindigkeit, | keine Entnahme der Sekundärfilterschicht. — printed p.14', verification_note='md-verified 2026-09-05 (§4, printed p.14) [VC]; note: attestation checkbox for gate REQ-07 (the four §4 Grundlagen); duplicated on M187-05 (STAGED S-2)', verified_at=now() where id='d21ef90e-49c7-46ed-b07f-d2532b84f567' and verification_status not in ('verified_against_standard','corrected');

