-- h_FK
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {FK }}$ & m & Höhe Filterkörper | Der Filterkörper muss in Abweichung von den Festlegungen in Arbeitsblatt DWA-A 178 unabhängig von der Art des Entwässerungssystems (Misch- oder Trennsystem) eine Höhe von $h_{F K} \geqslant 1,00 \mathrm{~m}$ haben. — printed p.13 and p.18–19', verification_note='md-verified 2026-09-05 (§3.2 / §5.1.3.2 b), printed p.13 and p.18–19) [VC]; note: the 1,00 m limit is P-Variante b) only; other limits: §5.2.3.1 b)/c) ≥ 1 m, §5.3.3.1 sollte ≥ 1,0 m, §5.5.3.2.2 ≥ 0,25 m (0,2 m with Carbonatschicht) — gate REQ-02 fires unconditionally (STAGED S-3)', verified_at=now() where id='2bcbe365-a2d7-4362-aaad-a29b33890538' and verification_status not in ('verified_against_standard','corrected');
-- verfahrensvariante_p
update public.fields set verification_status='verified_against_standard', verification_quote='Ausgehend von einer RBFA (Vorstufe und RBF) können mehrere Verfahrensvarianten betrachtet werden (siehe Bild 2): a) Fällung Filterzulauf: Bei Neubau oder Ertüchtigung vorhandener RBFA erfolgt eine P -Fällung im Filterzulauf. b) Melioration Filtermaterial: Hier werden bei Neubau zur Steigerung der P-Bindekapazität eisenhaltige Zuschlagstoffe in das Filtermaterial eingemischt. c) Nachgeschaltete Sorptionsstufe: Bei Neubau oder Ertüchtigung vorhandener RBFA erfolgt eine separate P-Sorption des Filterablaufs über eine nachgeschaltete Sorptionsstufe. — printed p.15', verification_note='md-verified 2026-09-05 (§5.1.1 / §5.1.2, printed p.15) [VC]', verified_at=now() where id='8e356cc3-0940-4065-a6dd-f51688ac8f9b' and verification_status not in ('verified_against_standard','corrected');
-- beta_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Definitionen | Beta-Wert & $\beta$-Wert & Maß für die Fällmittelmenge, um eine bestimmte gelöste Stoffmenge in einen Feststoff zu überführen. Ein BetaWert von 1 bedeutet, dass die Fällmittelmenge genau der Menge des zu fällenden Stoffs entspricht. | Basierend auf einer mittleren $\mathrm{PO}_{4}$-Zulaufkonzentration von $S_{\text {P04-P, aM }}=0,5 \mathrm{mg} / \mathrm{l}$ kann die Menge des Fällmittels (Eisen-III-Salz) mit einem Beta-Wert von $\geqslant 4$ angesetzt werden. Diese Dosiermenge ist im laufenden Betrieb hinsichtlich der Zielkonzentration und der Fällmittelausnutzung zu optimieren. — printed p.11 and p.18', verification_note='md-verified 2026-09-05 (§3.1 Tab. 1 / §5.1.3.1 a), printed p.11 and p.18) [VC]; note: source wording "kann ... angesetzt werden", variant a) "in Entwicklung" (STAGED S-3/S-5)', verified_at=now() where id='bc588e5a-40cf-46a2-b182-ebdb379110dc' and verification_status not in ('verified_against_standard','corrected');
-- EBCT
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Definitionen | Filterkontaktzeit & EBCT & engl. Empty Bed Contact Time; hydraulische Filterkontaktzeit entspricht dem Quotienten aus Filtervolumen und Zufluss; Zeitspanne, für die eine Flüssigkeit in Kontakt mit dem Filtermaterial steht | Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. — printed p.11 and p.18', verification_note='md-verified 2026-09-05 (§3.1 Tab. 1 / §5.1.3.1 c), printed p.11 and p.18) [VC]; note: P-Variante c) only; "können ... angesetzt werden" (halbtechnisch)', verified_at=now() where id='a7c3db2f-ebf4-4be3-ae21-b802a77cc6b8' and verification_status not in ('verified_against_standard','corrected');
-- S_PO4P_RBF_ab
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $S_{\text {P04-P, RBF, ab }}$ & mg/l & Ablaufkonzentration des gelösten Phosphors zum Retentionsbodenfilter | Bei allen Anlagen konnten über einen Zeitraum von 20 Jahren eine mittlere Ablaufkonzentration von $S_{\text {P04-P, RBF, ab }}<0,03 \mathrm{mg} / \mathrm{l}$ erreicht werden. — printed p.13 and p.16', verification_note='md-verified 2026-09-05 (§3.2 / §5.1.2 b), printed p.13 and p.16) [VC]; note: the < 0,03 mg/l is a reported operating result (Erfahrungen), not a design limit', verified_at=now() where id='bcc56333-d7d0-48ca-b420-154e9da49795' and verification_status not in ('verified_against_standard','corrected');
-- S_PO4P_RBF_zu
