update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $S_{\text {P04-P,SS,ab }}$ & mg/ & Ablaufkonzentration des gelösten Phosphors zur Sorptionsstufe | Bei einer frachtgewichteten mittleren Zulaufkonzentration von $S_{\mathrm{PO} 4-\mathrm{P}, \mathrm{SS}, \mathrm{zu}}=0,91 \mathrm{mg} / \mathrm{l}$ betrug die maximale frachtgewichtete Ablaufkonzentration $S_{\text {P04-P, SS, ab }}<0,02 \mathrm{mg} / \mathrm{l}$. — printed p.13 and p.16', verification_note='md-verified 2026-09-05 (§3.2 / §5.1.2 c), printed p.13 and p.16) [VC]; note: Tab. 2 unit prints as "mg/" (transcript truncation of mg/l); the < 0,02 mg/l is a halbtechnisch operating result, not a design limit', verified_at=now() where id='929fb4b0-1cfd-41af-a21c-31d9c168d8ab' and verification_status not in ('verified_against_standard','corrected');
