-- Fe_gehalt
update public.fields set verification_status='verified_against_standard', verification_quote='Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. | Als Anforderung für den adsorbierenden Stoff in Form von Eisenhydroxid gelten neben der Schadstofffreiheit gemäß LAGA (2003) ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbelastung von $C_{\mathrm{P}}<0,2 \mathrm{~g} / \mathrm{kg}$. — printed p.18–19', verification_note='md-verified 2026-09-05 (§5.1.3.2 b) and c), printed p.18–19) [VC]', verified_at=now() where id='e6a917fc-d6ba-4e78-bca5-55e2948843e5' and verification_status not in ('verified_against_standard','corrected');
