-- v_filter_aufstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden. — printed p.18', verification_note='md-verified 2026-09-05 (§5.1.3.1 c), printed p.18) [VC]', verified_at=now() where id='0eba7382-b44f-4389-9813-e14ba8428e3e' and verification_status not in ('verified_against_standard','corrected');
