-- ######################## M187-06 · P-Rückhalt: Übersicht & Variantenvergleich ########################
-- q_Dr_RBF
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $q_{\text {Dr,RBF }}$ & $\mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)^{2}$ & Drosselabflussspende eines Retentionsbodenfilters | Zu b) Bei einer Beimischung von GAK ist eine Filterschichtstärke von 1 m vorzusehen. Die Drosselabflussspende ist auf $q_{\mathrm{Dr}, \mathrm{RBF}} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. | Abweichend ist jedoch sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\mathrm{Dr}, \mathrm{RBF}}=0,01 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. — printed p.13, p.22 and p.25', verification_note='md-verified 2026-09-05 (§3.2 / §5.2.3.1 b)–c) / §5.3.3.1, printed p.13, p.22 and p.25) [VC]; note: Tab. 2 unit prints with a stray "^{2}" (transcript); limits: Spurenstoffe a) 0,01 (§5.2.3.1 a) p.22, quoted on M187-12), b)/c) ≤ 0,03, Mikroorganismen = 0,01 l/(s·m²) — gates REQ-03/REQ-04 on the P-Rückhalt worksheets (STAGED S-3)', verified_at=now() where id='84d81522-20fe-4399-ab72-a41cdb2338f5' and verification_status not in ('verified_against_standard','corrected');
-- verfahrensvariante_spurenstoffe
update public.fields set verification_status='verified_against_standard', verification_quote='Ausgehend von den in 5.2.1 beschriebenen Erfahrungen und weitergehenden Untersuchungen an halbtechnischen Anlagen wurden RBF für den Rückhalt von Spurenstoffen auf verschiedene Weisen optimiert durch: a) Erhöhung der Kontaktzeit durch Reduzierung der Drosselabflussspende $q_{\text {Dr, RBF }}$. b) Beimischung von granulierter Aktivkohle (GAK) zur Erhöhung der Adsorptionskapazität und Optimierung der mikrobiellen Leistungsfähigkeit. c) Mitbehandlung des Kläranlagenablaufs zur gezielten Spurenstoffelimination nach Beimischung von granulierter Aktivkohle. d) Nachschaltung einer zusätzlichen Behandlungsstufe, bestehend aus anorganischen oder organischen Adsorbern. — printed p.21', verification_note='md-verified 2026-09-05 (§5.2.2, printed p.21) [VC]', verified_at=now() where id='cad7e906-1f5e-4dbd-872c-327feb7986a6' and verification_status not in ('verified_against_standard','corrected');
-- verfahrensvariante_p
update public.fields set verification_status='verified_against_standard', verification_quote='Ausgehend von einer RBFA (Vorstufe und RBF) können mehrere Verfahrensvarianten betrachtet werden (siehe Bild 2): a) Fällung Filterzulauf: Bei Neubau oder Ertüchtigung vorhandener RBFA erfolgt eine P -Fällung im Filterzulauf. b) Melioration Filtermaterial: Hier werden bei Neubau zur Steigerung der P-Bindekapazität eisenhaltige Zuschlagstoffe in das Filtermaterial eingemischt. c) Nachgeschaltete Sorptionsstufe: Bei Neubau oder Ertüchtigung vorhandener RBFA erfolgt eine separate P-Sorption des Filterablaufs über eine nachgeschaltete Sorptionsstufe. — printed p.15', verification_note='md-verified 2026-09-05 (§5.1.1 / §5.1.2, printed p.15) [VC]', verified_at=now() where id='db1e7f44-7ba1-4faa-bebc-b020f2384f97' and verification_status not in ('verified_against_standard','corrected');
-- DT50
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | DT50 & d & Zeit in Tagen, nach der 50 \% der Ausgangsmenge eines Stoffs abgebaut/verschwunden ist. Bei einem Abbau erster Ordnung entspricht dies der Halbwertszeit. — printed p.12', verification_note='md-verified 2026-09-05 (§3.2, printed p.12) [VC]; note: symbol defined in Tab. 2 only; not used in the body text', verified_at=now() where id='a1a059bd-f956-4ec4-956b-455667deeb59' and verification_status not in ('verified_against_standard','corrected');
-- Q_T_d_aM
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $Q_{\mathrm{T}, \mathrm{d}, \mathrm{am}}$ & $\mathrm{l} / \mathrm{s}$ & täglicher Trockenwetterabfluss im Jahresmittel | Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. — printed p.13 and p.22', verification_note='md-verified 2026-09-05 (§3.2 / §5.2.3.1 c), printed p.13 and p.22) [VC]; note: Tab. 2 prints the subscript as "am", §5.2.3.1 as "a M" (transcript)', verified_at=now() where id='77be6098-52e4-465a-8473-f2679de80976' and verification_status not in ('verified_against_standard','corrected');
