-- beschickungsdauer_segment
update public.fields set verification_status='verified_against_standard', verification_quote='Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. — printed p.22', verification_note='md-verified 2026-09-05 (§5.2.3.1 c), printed p.22) [VC]; note: "sollte" wording', verified_at=now() where id='ba14d870-8eb9-4caa-b9af-e64e9b07bb34' and verification_status not in ('verified_against_standard','corrected');
-- trockenzeit_nach_vollbeschickung
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. — printed p.22', verification_note='md-verified 2026-09-05 (§5.2.3.1 c), printed p.22) [VC]; note: "ist ... einzuhalten" — no gate on M187-14 (STAGED S-4)', verified_at=now() where id='c22e80b8-f60b-4ddf-9b0e-b76baa99c5fc' and verification_status not in ('verified_against_standard','corrected');

-- ######################## M187-07 · P-Rückhalt Variante a: Fällung Filterzulauf ########################
-- uv_eingesetzt
update public.fields set verification_status='verified_against_standard', verification_quote='Eine weitergehende Möglichkeit zur Elimination von Mikroorganismen stellt die UV-Bestrahlung des Ablaufs von RBF dar. Eine nachgeschaltete UV-Anlage erweist sich unter anderem aufgrund der geringen Trübung im Ablauf von RBF und der daraus resultierenden hohen Transmission als sehr wirksam. — printed p.27', verification_note='md-verified 2026-09-05 (§5.3.3.5, printed p.27) [VC]', verified_at=now() where id='89e8869b-4763-4529-871f-5764a65f89f5' and verification_status not in ('verified_against_standard','corrected');
-- beta_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Definitionen | Beta-Wert & $\beta$-Wert & Maß für die Fällmittelmenge, um eine bestimmte gelöste Stoffmenge in einen Feststoff zu überführen. Ein BetaWert von 1 bedeutet, dass die Fällmittelmenge genau der Menge des zu fällenden Stoffs entspricht. | Basierend auf einer mittleren $\mathrm{PO}_{4}$-Zulaufkonzentration von $S_{\text {P04-P, aM }}=0,5 \mathrm{mg} / \mathrm{l}$ kann die Menge des Fällmittels (Eisen-III-Salz) mit einem Beta-Wert von $\geqslant 4$ angesetzt werden. Diese Dosiermenge ist im laufenden Betrieb hinsichtlich der Zielkonzentration und der Fällmittelausnutzung zu optimieren. — printed p.11 and p.18', verification_note='md-verified 2026-09-05 (§3.1 Tab. 1 / §5.1.3.1 a), printed p.11 and p.18) [VC]; note: source wording "kann ... angesetzt werden", variant a) "in Entwicklung" (STAGED S-3/S-5)', verified_at=now() where id='5b48a47c-e025-4e64-b5b1-2cffd34a4166' and verification_status not in ('verified_against_standard','corrected');
-- KBE
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | KBE & Anzahl/ 100 ml & Anzahl der Kolonie bildende Mikroorganismen (Einheiten) | In Mischwasserentlastungen liegen die frachtgemittelten Ereigniskonzentrationen von Indikatororganismen im Großteil aller erfassten Ereignisse im Bereich von $10^{4} \mathrm{KBE} / 100 \mathrm{ml}$ bis $10^{7} \mathrm{KBE} / 100 \mathrm{ml}$ für E. coli [...] — printed p.13 and p.24–25', verification_note='md-verified 2026-09-05 (§3.2 / §5.3.2, printed p.13 and p.24–25) [VC]', verified_at=now() where id='29100c06-4fb6-4e31-9836-f08cafb213fd' and verification_status not in ('verified_against_standard','corrected');
-- MPN
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | MPN & Anzahl/ 100 ml & engl. Most Probable Number; statistisches Auswerteverfahren zur Feststellung der Belastung mit Mikroorganismen | In einem Trennkanalsystem wurden Zulaufkonzentrationen für E. coli und intestinale Enterokokken von $10^{2} \mathrm{MPN} / 100 \mathrm{ml}$ bis $10^{6} \mathrm{MPN} / 100 \mathrm{ml}$ erfasst. Coliphagen lagen zwischen $10 \mathrm{PBE} / 100 \mathrm{ml}$ und $10^{5} \mathrm{PBE} / 100 \mathrm{ml}$ (MERTENS et al. 2014). — printed p.13 and p.24–25', verification_note='md-verified 2026-09-05 (§3.2 / §5.3.2, printed p.13 and p.24–25) [VC]', verified_at=now() where id='7e571d9c-3765-4c56-988c-6ab7f011efdc' and verification_status not in ('verified_against_standard','corrected');
-- PBE
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | PBE & Anzahl/ 100 ml & Anzahl der Plaque bildende Mikroorganismen (Einheiten) | In Mischwasserentlastungen liegen die frachtgemittelten Ereigniskonzentrationen von Indikatororganismen [...] und $10^{3} \mathrm{PBE} / 100 \mathrm{ml}$ bis $10^{5} \mathrm{PBE} / 100 \mathrm{ml}$ für somatische Coliphagen (Tondera et al. 2013). — printed p.13 and p.24–25', verification_note='md-verified 2026-09-05 (§3.2 / §5.3.2, printed p.13 and p.24–25) [VC]', verified_at=now() where id='58c1bbad-3238-4e8b-b63d-a64b1416ff9d' and verification_status not in ('verified_against_standard','corrected');
-- S_PO4P_aM
update public.fields set verification_status='verified_against_standard', verification_quote='Basierend auf einer mittleren $\mathrm{PO}_{4}$-Zulaufkonzentration von $S_{\text {P04-P, aM }}=0,5 \mathrm{mg} / \mathrm{l}$ kann die Menge des Fällmittels (Eisen-III-Salz) mit einem Beta-Wert von $\geqslant 4$ angesetzt werden. Diese Dosiermenge ist im laufenden Betrieb hinsichtlich der Zielkonzentration und der Fällmittelausnutzung zu optimieren. — printed p.18', verification_note='md-verified 2026-09-05 (§5.1.3.1 a), printed p.18) [VC]; note: symbol S_P04-P,aM is used only here (not in Tab. 2)', verified_at=now() where id='71aa114e-f995-45ca-be4e-47de64de6d80' and verification_status not in ('verified_against_standard','corrected');
-- UV_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Bemessung einer nachgeschalteten UV-Bestrahlung sollte nach derzeitiger Kenntnis in Anlehnung an SCHÖLER (2002) eine Mindestdosis von $200 \mathrm{~J} / \mathrm{m}^{2}$ nicht unterschritten werden. — printed p.27', verification_note='md-verified 2026-09-05 (§5.3.3.5, printed p.27) [VC]; note: "sollte ... nicht unterschritten werden", in Anlehnung an SCHÖLER (2002)', verified_at=now() where id='16c417ea-00cd-421a-a8ad-136023356b90' and verification_status not in ('verified_against_standard','corrected');
-- logstufen_rueckhalt
update public.fields set verification_status='verified_against_standard', verification_quote='Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \mathrm{Log}$-Stufen bis $1,5 \mathrm{Log}$-Stufen auftreten. | Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018). — printed p.24–25 and p.25', verification_note='md-verified 2026-09-05 (§5.3.2 / §5.3.3.1, printed p.24–25 and p.25) [VC]; note: a measured outcome (Erfahrungswerte), not a design input', verified_at=now() where id='0144ad68-f146-4b77-ad72-578ec720adb8' and verification_status not in ('verified_against_standard','corrected');
-- pufferschicht_carbonatbrechsand
update public.fields set verification_status='verified_against_standard', verification_quote='Der RBF sollte zusätzlich zur Deckschicht und der Carbonatausstattung nach Arbeitsblatt DWAA 178:2019 mit einer ca. 5 cm hohe Pufferschicht aus gewaschenem Carbonatbrechsand ( $>0,06 \mathrm{~mm}$ bis 2 mm ) ausgestattet werden. Diese Schicht dient der Vermeidung der Filtersedimentversauerung durch das Fällmittel. Im Neubau sollte die Pufferschicht zwischen Filtermaterial und Deckschicht eingebaut werden. — printed p.18', verification_note='md-verified 2026-09-05 (§5.1.3.2 a), printed p.18) [VC]; note: "sollte", "ca. 5 cm"', verified_at=now() where id='72d96425-ae0b-4043-86d1-a07a8f3090ce' and verification_status not in ('verified_against_standard','corrected');
-- betriebsdauer_jahre
update public.fields set verification_status='verified_against_standard', verification_quote='Die Dosieranlage sollte erst nach einem voll etablierten Schilfbestand und wenn die Rückhalteleistung des Filtermaterials abnimmt, in Betrieb genommen werden. Bei nach Arbeitsblatt DWA-A 178:2019 bemessenen RBF ist letzteres nach 2 bis 3 Betriebsjahren der Fall. — printed p.20', verification_note='md-verified 2026-09-05 (§5.1.4.1 a), printed p.20) [VC]; note: "sollte"; 2 bis 3 Betriebsjahre is an experience value', verified_at=now() where id='80b11c15-9830-478a-b6dc-6bf56b79f1e1' and verification_status not in ('verified_against_standard','corrected');

