-- h_FK
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {FK }}$ & m & Höhe Filterkörper | Der Filterkörper muss in Abweichung von den Festlegungen in Arbeitsblatt DWA-A 178 unabhängig von der Art des Entwässerungssystems (Misch- oder Trennsystem) eine Höhe von $h_{F K} \geqslant 1,00 \mathrm{~m}$ haben. — printed p.13 and p.18–19', verification_note='md-verified 2026-09-05 (§3.2 / §5.1.3.2 b), printed p.13 and p.18–19) [VC]; note: the 1,00 m limit is P-Variante b) only; other limits: §5.2.3.1 b)/c) ≥ 1 m, §5.3.3.1 sollte ≥ 1,0 m, §5.5.3.2.2 ≥ 0,25 m (0,2 m with Carbonatschicht) — gate REQ-02 fires unconditionally (STAGED S-3)', verified_at=now() where id='40e9337f-7b7c-4e8e-9e10-2236e0e45687' and verification_status not in ('verified_against_standard','corrected');
-- q_A_max
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $q_{\mathrm{A}, \max }$ & $\mathrm{m} / \mathrm{h}$ & maximale Oberflächenbeschickung | Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.13 and p.30', verification_note='md-verified 2026-09-05 (§3.2 / §5.4.3, printed p.13 and p.30) [VC]', verified_at=now() where id='d7a21692-1075-4799-9431-5bf1c1bff506' and verification_status not in ('verified_against_standard','corrected');
-- q_krit
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $q_{\text {krit }}$ & l/(s•ha) & kritische Abfussspende | Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.13 and p.30', verification_note='md-verified 2026-09-05 (§3.2 / §5.4.3, printed p.13 and p.30) [VC]; note: "sollte"; §5.4.4 repeats "Der Durchfluss der Vorstufe wird auf $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot$ ha $)$ begrenzt." (p.31); Tab. 2 prints "Abfussspende" (transcript)', verified_at=now() where id='92291b3d-67ac-45d8-b94b-3e21068b192c' and verification_status not in ('verified_against_standard','corrected');
