-- Fe_gehalt
update public.fields set verification_status='verified_against_standard', verification_quote='Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. | Als Anforderung für den adsorbierenden Stoff in Form von Eisenhydroxid gelten neben der Schadstofffreiheit gemäß LAGA (2003) ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbelastung von $C_{\mathrm{P}}<0,2 \mathrm{~g} / \mathrm{kg}$. — printed p.18–19', verification_note='md-verified 2026-09-05 (§5.1.3.2 b) and c), printed p.18–19) [VC]', verified_at=now() where id='35f16301-bc07-4707-98dd-61205ece8373' and verification_status not in ('verified_against_standard','corrected');
-- p_grund_beladung
update public.fields set verification_status='verified_against_standard', verification_quote='Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. — printed p.18–19', verification_note='md-verified 2026-09-05 (§5.1.3.2 b), printed p.18–19) [VC]; note: §5.1.3.2 c) repeats the limit as "P-Grundbelastung von $C_{\mathrm{P}}<0,2 \mathrm{~g} / \mathrm{kg}$"', verified_at=now() where id='4fcf3e28-2388-4427-9a4e-dee9bb1bdc1b' and verification_status not in ('verified_against_standard','corrected');
-- Fe_massenanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. — printed p.18–19', verification_note='md-verified 2026-09-05 (§5.1.3.2 b), printed p.18–19) [VC]; note: empirical value ("gute Ergebnisse"), §5.1.2 b) reports 7 % bis 10 % in built plants; not a hard limit', verified_at=now() where id='e21e56b1-106d-47b3-a78e-a0c691a9c023' and verification_status not in ('verified_against_standard','corrected');
-- feinmassenanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einem Feinmassenanteil > $5 \%$ im fertig gemischten Filtermaterial muss die hydraulische Eignung des Filtermaterials durch Versuche belegt werden. Die Grundanforderungen gemäß Arbeitsblatt DWA-A 178:2019 sind einzuhalten. — printed p.18–19', verification_note='md-verified 2026-09-05 (§5.1.3.2 b), printed p.18–19) [VC]', verified_at=now() where id='5685ff8a-98c7-4584-9eea-037559ebd69f' and verification_status not in ('verified_against_standard','corrected');
-- V_vorstufe_min
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.30', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30) [VC]; note: "empfohlen"', verified_at=now() where id='bffd8594-0b41-4380-a616-7f271e0d96fc' and verification_status not in ('verified_against_standard','corrected');
-- B_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]', verified_at=now() where id='d3222e72-9d64-4bca-b7d6-5468b60209d9' and verification_status not in ('verified_against_standard','corrected');
-- A_F_pro_AEb
update public.fields set verification_status='verified_against_standard', verification_quote='Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]; note: the 750 m²/ha floor applies only "Liegen keine Daten vor" — gate REQ-05 enforces it unconditionally (STAGED S-3)', verified_at=now() where id='deb2ad84-d140-4b3f-99c3-d90769b2f123' and verification_status not in ('verified_against_standard','corrected');
-- foerderleistung_beschickung
update public.fields set verification_status='verified_against_standard', verification_quote='Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]', verified_at=now() where id='034fc708-1dd3-427b-bde7-8d7e0d9dacb3' and verification_status not in ('verified_against_standard','corrected');
