-- austritts_dichte
update public.fields set verification_status='verified_against_standard', verification_quote='Es muss ein gleichmäßiges engmaschiges Verteilungsnetz auf der Filterbeckenoberfläche installiert werden. Die beschickte Filterfläche sollte $\leqslant 1 \mathrm{~m}^{2}$ /Austrittsöffnung betragen. — printed p.31', verification_note='md-verified 2026-09-05 (§5.4.4, printed p.31) [VC]; note: "sollte"', verified_at=now() where id='c34041f7-e5b8-4aef-993b-2bc0b2829c95' and verification_status not in ('verified_against_standard','corrected');
-- CSB_grenze_trennung
update public.fields set verification_status='verified_against_standard', verification_quote='Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). — printed p.29', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29) [VC]; note: standard_fixed 3.000 mg/l (LAWA 2018) stored as an editable number (STAGED S-6)', verified_at=now() where id='a83b6dbe-22bc-4338-aaad-dfe3873d4df4' and verification_status not in ('verified_against_standard','corrected');
-- CSB_konzentration
update public.fields set verification_status='verified_against_standard', verification_quote='Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). — printed p.29', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29) [VC]; note: no gate compares it with the 3.000 mg/l threshold (STAGED S-4)', verified_at=now() where id='d4e7feb7-0144-4f14-8f5c-d32f94c6cbe4' and verification_status not in ('verified_against_standard','corrected');
-- wirkungsgrad_hydraulisch
update public.fields set verification_status='verified_against_standard', verification_quote='Wegen der hohen zu erwartenden Stoffkonzentrationen muss der RBF auf eine Vollstrombehandlung mit $100 \%$ hydraulischem Wirkungsgrad ausgelegt werden. Der Notüberlauf des Filters stellt nur eine zusätzliche Sicherheit zum Schutz der Anlage dar. — printed p.29–30', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29–30) [VC]; note: standard_fixed 100 % stored as an editable number; no gate (STAGED S-4/S-6)', verified_at=now() where id='f08da7e8-cb12-4f32-af07-23f59556b5bb' and verification_status not in ('verified_against_standard','corrected');
-- A_E_b
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $A_{\mathrm{E}, \mathrm{b}}$ & ha & Einzugsgebietsfläche; Summe aller befestigten, angeschlossenen Flächen eines Einzugsgebiets | Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen. — printed p.12 and p.30–31', verification_note='md-verified 2026-09-05 (§3.2 / §5.4.3, printed p.12 and p.30–31) [VC]', verified_at=now() where id='065809ba-14e6-47b3-bf72-0e065401fb76' and verification_status not in ('verified_against_standard','corrected');
-- fallhoehe_einbau
update public.fields set verification_status='verified_against_standard', verification_quote='Um eine gleichmäßige Filterdurchlässigkeit des Filters zu gewährleisten, ist das meliorierte Filtermaterial möglichst verdichtungsfrei einzubauen. Dies kann zum Beispiel über einen Teleskopausleger erfolgen. Zur Gewährleistung des entmischungsfreien Einbaus sind Fallhöhen von $\leqslant 1,0 \mathrm{~m}$ einzuhalten. — printed p.20', verification_note='md-verified 2026-09-05 (§5.1.3.4 b), printed p.20) [VC]', verified_at=now() where id='c384009f-bfe2-45b7-9cd2-113cd650b693' and verification_status not in ('verified_against_standard','corrected');

