-- CaCO3_massenanteil_carbo
update public.fields set verification_status='verified_against_standard', verification_quote='Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtermaterial, printed p.36) [VC]; note: standard_fixed 80 % stored as an editable number (STAGED S-6)', verified_at=now() where id='b4d184bb-7c95-4445-89d1-db6b559d9e29' and verification_status not in ('verified_against_standard','corrected');
-- A_F_anteil_Aba
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden. — printed p.37', verification_note='md-verified 2026-09-05 (§5.5.4, printed p.37) [VC]; note: A_F < 1,0 % is allowed with the b_krit Nachweis (next paragraph) — gate REQ-06 pins == 1.0 (STAGED S-3)', verified_at=now() where id='e0e47030-89bf-4573-bcfb-0770768a8298' and verification_status not in ('verified_against_standard','corrected');
-- v_filter_aufstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden. — printed p.18', verification_note='md-verified 2026-09-05 (§5.1.3.1 c), printed p.18) [VC]', verified_at=now() where id='3f7f5c18-bb45-4f89-b6cc-d21a0338f760' and verification_status not in ('verified_against_standard','corrected');
-- carbonatschicht_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtermaterial, printed p.36) [VC]', verified_at=now() where id='aa0f425d-9c77-4471-ad2a-89c8ca160b10' and verification_status not in ('verified_against_standard','corrected');
