-- b_krit
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $b_{\text {krit }}$ & $\mathrm{kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ & zulässige spezifische jährliche Filterflächenbelastung mit AFS63 | Mit entsprechender Nachweisführung [...] (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ [...] möglich. — printed p.12 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.12 and p.37) [VC]; note: value 7 kg/(m²·a) is inherited from DWA-A 178:2019; stored as an editable number (STAGED S-6)', verified_at=now() where id='a7f1126f-c1f7-42e4-b105-a87d7e460baa' and verification_status not in ('verified_against_standard','corrected');
-- b_R_a
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $b_{\mathrm{R}, \mathrm{a}}$ & kg/(ha•a) & mittlere spezifische AFS63-Jahresfrachtpotenziale des Regenwasserabflusses bezogen auf die Einzugsgebietsfläche $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ | Mit entsprechender Nachweisführung [...] (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ [...] möglich. — printed p.12 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.12 and p.37) [VC]; note: Tab. 2 refers to "A_E,b,a", a symbol Tab. 2 itself does not define (source/transcript quirk)', verified_at=now() where id='0bd652e0-5617-4908-be68-9f16d7c1a5fa' and verification_status not in ('verified_against_standard','corrected');
-- EBCT
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Definitionen | Filterkontaktzeit & EBCT & engl. Empty Bed Contact Time; hydraulische Filterkontaktzeit entspricht dem Quotienten aus Filtervolumen und Zufluss; Zeitspanne, für die eine Flüssigkeit in Kontakt mit dem Filtermaterial steht | Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. — printed p.11 and p.18', verification_note='md-verified 2026-09-05 (§3.1 Tab. 1 / §5.1.3.1 c), printed p.11 and p.18) [VC]; note: P-Variante c) only; "können ... angesetzt werden" (halbtechnisch)', verified_at=now() where id='940faadd-79da-428b-a1e5-657cef38c1ab' and verification_status not in ('verified_against_standard','corrected');
-- h_Draen
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {Drän }}$ & m & Schichtdicke des Dränmaterials | Die Dränage muss mindestens in DN 50 ungedrosselt ausgeführt werden. Die Drosselung erfolgt über den Fließwiderstand des Filtermaterials. Die Schichtdicke des Dränmaterials sollte mindestens $h_{\text {Drän }} \geqslant 0,1 \mathrm{~m}$ betragen. — printed p.13 and p.36', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.3.2.2 Dränsystem, printed p.13 and p.36) [VC]; note: "sollte mindestens"', verified_at=now() where id='06145c85-7660-435e-aa4c-294d0da38ce1' and verification_status not in ('verified_against_standard','corrected');
-- h_RBF
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {RBF }}$ & m & Einbautiefe eines Retentionsbodenfilterbecken | In Bild 8 sind die aufgeführten vertikalen Mindestmaße und Proportionen beispielhaft für einen Filterkörper mit Deckschicht dargestellt. Mit diesem Aufbau sind Klein-RBF mit einer Einbautiefe von lediglich $h_{\text {RBF }} \geqslant 0,6 \mathrm{~m}$ möglich, was insbesondere bei flacher Topografie, geringen Gefälleverhältnissen und/oder geringer Tiefenverfügbarkeit vorteilhaft ist. — printed p.13 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.3.2.2, printed p.13 and p.37) [VC]; note: "≥ 0,6 m möglich" describes the achievable minimum depth of the Bild 8 build-up, not a requirement — gate REQ-06 treats it as a floor (STAGED S-3)', verified_at=now() where id='21fa5c7a-9523-4bf0-a334-5fc4b0dba812' and verification_status not in ('verified_against_standard','corrected');
-- h_RR
