-- h_FK_CaCO3
update public.fields set verification_status='verified_against_standard', verification_quote='Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtermaterial, printed p.36) [VC]; note: no gate ≥ 0,10 m when carbonatschicht_vorhanden = ja (STAGED S-4)', verified_at=now() where id='3db63626-77f2-46c5-ad1c-3bce620933c3' and verification_status not in ('verified_against_standard','corrected');
-- eta_AFS63
