-- ######################## M187-11 · Spurenstoffelimination: Übersicht ########################
-- verfahrensvariante_spurenstoffe
update public.fields set verification_status='verified_against_standard', verification_quote='Ausgehend von den in 5.2.1 beschriebenen Erfahrungen und weitergehenden Untersuchungen an halbtechnischen Anlagen wurden RBF für den Rückhalt von Spurenstoffen auf verschiedene Weisen optimiert durch: a) Erhöhung der Kontaktzeit durch Reduzierung der Drosselabflussspende $q_{\text {Dr, RBF }}$. b) Beimischung von granulierter Aktivkohle (GAK) zur Erhöhung der Adsorptionskapazität und Optimierung der mikrobiellen Leistungsfähigkeit. c) Mitbehandlung des Kläranlagenablaufs zur gezielten Spurenstoffelimination nach Beimischung von granulierter Aktivkohle. d) Nachschaltung einer zusätzlichen Behandlungsstufe, bestehend aus anorganischen oder organischen Adsorbern. — printed p.21', verification_note='md-verified 2026-09-05 (§5.2.2, printed p.21) [VC]', verified_at=now() where id='8a88f32d-9871-40f7-8f21-2eeb9baa4cfe' and verification_status not in ('verified_against_standard','corrected');

