-- logstufen_rueckhalt
update public.fields set verification_status='verified_against_standard', verification_quote='Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \mathrm{Log}$-Stufen bis $1,5 \mathrm{Log}$-Stufen auftreten. | Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018). — printed p.24–25 and p.25', verification_note='md-verified 2026-09-05 (§5.3.2 / §5.3.3.1, printed p.24–25 and p.25) [VC]; note: a measured outcome (Erfahrungswerte), not a design input', verified_at=now() where id='9220d8de-36f0-4602-babd-827fce810c9a' and verification_status not in ('verified_against_standard','corrected');

