update public.fields set verification_status='verified_against_standard', verification_quote='Eine weitergehende Möglichkeit zur Elimination von Mikroorganismen stellt die UV-Bestrahlung des Ablaufs von RBF dar. Eine nachgeschaltete UV-Anlage erweist sich unter anderem aufgrund der geringen Trübung im Ablauf von RBF und der daraus resultierenden hohen Transmission als sehr wirksam. — printed p.27', verification_note='md-verified 2026-09-05 (§5.3.3.5, printed p.27) [VC]', verified_at=now() where id='3e7a201e-c2d5-4027-9a24-383b316fc8a7' and verification_status not in ('verified_against_standard','corrected');
-- UV_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Bemessung einer nachgeschalteten UV-Bestrahlung sollte nach derzeitiger Kenntnis in Anlehnung an SCHÖLER (2002) eine Mindestdosis von $200 \mathrm{~J} / \mathrm{m}^{2}$ nicht unterschritten werden. — printed p.27', verification_note='md-verified 2026-09-05 (§5.3.3.5, printed p.27) [VC]; note: "sollte ... nicht unterschritten werden", in Anlehnung an SCHÖLER (2002)', verified_at=now() where id='1d478342-ad1f-4031-bdf6-1fa3773c1908' and verification_status not in ('verified_against_standard','corrected');

-- ######################## M187-19 · Hohe organische Belastung: Vorstufe ########################
-- q_A_max
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $q_{\mathrm{A}, \max }$ & $\mathrm{m} / \mathrm{h}$ & maximale Oberflächenbeschickung | Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.13 and p.30', verification_note='md-verified 2026-09-05 (§3.2 / §5.4.3, printed p.13 and p.30) [VC]', verified_at=now() where id='ff4c2964-64bd-49ab-bb46-1a5ab2071721' and verification_status not in ('verified_against_standard','corrected');
-- q_krit
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $q_{\text {krit }}$ & l/(s•ha) & kritische Abfussspende | Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.13 and p.30', verification_note='md-verified 2026-09-05 (§3.2 / §5.4.3, printed p.13 and p.30) [VC]; note: "sollte"; §5.4.4 repeats "Der Durchfluss der Vorstufe wird auf $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot$ ha $)$ begrenzt." (p.31); Tab. 2 prints "Abfussspende" (transcript)', verified_at=now() where id='cb99082c-fc01-4e4d-aeea-57c7a9962d16' and verification_status not in ('verified_against_standard','corrected');
-- V_vorstufe_min
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. — printed p.30', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30) [VC]; note: "empfohlen"', verified_at=now() where id='dfc5dd23-b5cb-4f2d-a62b-4499ea8b1df5' and verification_status not in ('verified_against_standard','corrected');
-- CSB_grenze_trennung
update public.fields set verification_status='verified_against_standard', verification_quote='Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). — printed p.29', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29) [VC]; note: standard_fixed 3.000 mg/l (LAWA 2018) stored as an editable number (STAGED S-6)', verified_at=now() where id='17db634a-6cdf-4c55-8ef6-f342d4c3a4f2' and verification_status not in ('verified_against_standard','corrected');
-- CSB_konzentration
update public.fields set verification_status='verified_against_standard', verification_quote='Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). — printed p.29', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29) [VC]; note: no gate compares it with the 3.000 mg/l threshold (STAGED S-4)', verified_at=now() where id='5fb5a0aa-c790-4562-a022-c757af72de4d' and verification_status not in ('verified_against_standard','corrected');
-- sickerwasser_in_rbf
update public.fields set verification_status='verified_against_standard', verification_quote='Das Niederschlagswasser der Betriebsflächen darf in die RBFA eingeleitet werden. Das Sickerwasser ist für eine Behandlung mit einem RBF zu hoch belastet und darf daher nicht in die RBFA eingeleitet werden. — printed p.29', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29) [VC]; note: "darf ... nicht" — no gate == false (STAGED S-4)', verified_at=now() where id='b91aedb8-f701-4cb9-aad7-b4c8f8297ebd' and verification_status not in ('verified_against_standard','corrected');

