update public.fields set verification_status='verified_against_standard', verification_quote='Wegen der hohen zu erwartenden Stoffkonzentrationen muss der RBF auf eine Vollstrombehandlung mit $100 \%$ hydraulischem Wirkungsgrad ausgelegt werden. Der Notüberlauf des Filters stellt nur eine zusätzliche Sicherheit zum Schutz der Anlage dar. — printed p.29–30', verification_note='md-verified 2026-09-05 (§5.4.2.2.2, printed p.29–30) [VC]; note: source mandates Vollstrombehandlung only; the enum option "teilstrom" is an EKOWAI addition (no gate rejects it — STAGED S-4)', verified_at=now() where id='ed116bdd-99c6-4ef2-b325-d55b3066d659' and verification_status not in ('verified_against_standard','corrected');
-- foerderleistung_beschickung
update public.fields set verification_status='verified_against_standard', verification_quote='Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]', verified_at=now() where id='3214750d-78c3-4d16-8661-8c7055335c1b' and verification_status not in ('verified_against_standard','corrected');
