-- B_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]', verified_at=now() where id='09630c1e-6cb3-4ea9-9fc0-2595e73a4707' and verification_status not in ('verified_against_standard','corrected');
