-- anzahl_teilfilter
update public.fields set verification_status='verified_against_standard', verification_quote='Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.4.3, printed p.30–31) [VC]; note: vier oder ein Vielfaches von vier — no gate (STAGED S-4)', verified_at=now() where id='a4f17cc8-d1a4-49d0-948a-7291d1883714' and verification_status not in ('verified_against_standard','corrected');

-- ######################## M187-21 · Klein-RBF: Anlagenkomponenten ########################
-- h_Draen
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {Drän }}$ & m & Schichtdicke des Dränmaterials | Die Dränage muss mindestens in DN 50 ungedrosselt ausgeführt werden. Die Drosselung erfolgt über den Fließwiderstand des Filtermaterials. Die Schichtdicke des Dränmaterials sollte mindestens $h_{\text {Drän }} \geqslant 0,1 \mathrm{~m}$ betragen. — printed p.13 and p.36', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.3.2.2 Dränsystem, printed p.13 and p.36) [VC]; note: "sollte mindestens"', verified_at=now() where id='531d8abd-771c-4bbc-858c-6f04abfab501' and verification_status not in ('verified_against_standard','corrected');
-- h_RR
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {RR }}$ & m & nutzbare Höhe/Tiefe des Retentionsraums (gemessen von der Bodenfilteroberfläche bis Höhe Filterbeckenüberlauf) | Der Retentionsraum dient der Zwischenspeicherung und der Sedimentation der durch Filtration zu behandelnden Regenwasserabflüsse. Die nutzbare Einstauhöhe beträgt $h_{R R} \geqslant 0,2 \mathrm{~m}$. — printed p.13 and p.35–36', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.3.2.2 Retentionsraum, printed p.13 and p.35–36) [VC]', verified_at=now() where id='d2b3b8fc-79ba-4ef4-9613-acb7aac9c2a4' and verification_status not in ('verified_against_standard','corrected');
-- h_FK_CaCO3
update public.fields set verification_status='verified_against_standard', verification_quote='Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtermaterial, printed p.36) [VC]; note: no gate ≥ 0,10 m when carbonatschicht_vorhanden = ja (STAGED S-4)', verified_at=now() where id='f8ff9ec4-3218-480b-a32f-b0e6f1278a3b' and verification_status not in ('verified_against_standard','corrected');
-- CaCO3_massenanteil_filter
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtermaterial, printed p.36) [VC]; note: limit inherited from DWA-A 178:2019; no gate ≥ 20 % (STAGED S-4)', verified_at=now() where id='3e953754-0b74-4f6f-ac1a-18f199ccd0af' and verification_status not in ('verified_against_standard','corrected');
-- CaCO3_massenanteil_carbo
