-- deckschicht_staerke
update public.fields set verification_status='verified_against_standard', verification_quote='Sie besteht aus einer 5 cm starken Schicht aus kantengerundetem oder gebrochenem mineralischem Material ( 2 mm bis 8 mm ). Das Material der Deckschicht muss frost- und tausalzbeständig sein. — printed p.35–36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Deckschicht, printed p.35–36) [VC]; note: printed "5 cm" — field unit is m (0,05); consider cm like pufferschicht_carbonatbrechsand (STAGED S-7)', verified_at=now() where id='bedbbeb5-a86d-4d9d-b65e-80c925f79e69' and verification_status not in ('verified_against_standard','corrected');
-- filtervegetation
update public.fields set verification_status='verified_against_standard', verification_quote='Aus technischer Sicht ist eine Filtervegetation nicht zwingend erforderlich. Im Sinne einer wasserbewussten Stadt- und Grünplanung sind die Klein-RBF zu bepflanzen. Nicht geeignet sind Gewächse, durch welche die Filterfähigkeit eingeschränkt und/oder die Anlagenkonstruktion gefährdet wird. Hierzu gehören starke Wurzelbildner wie Gehölze oder Schilf. | Es eignen sich insbesondere für den Siedlungsbereich vorgesehene Ansaaten mit blütenreichen mehrjährigen Regio-Mischungen. Diese lassen sich je nach Wasseranfall (Feuchte) kombinieren mit einzelnen Staudenpflanzungen. — printed p.36', verification_note='md-verified 2026-09-05 (§5.5.3.2.2 Filtervegetation, printed p.36) [VC]; note: enum options map to the source: Regio-Mischungen/Stauden = geeignet, Gehölze/Schilf = nicht geeignet, keine = "nicht zwingend erforderlich"; no gate rejects gehoelze/schilf (STAGED S-4)', verified_at=now() where id='18f5f3ab-6e3b-46c9-aa82-928e210cccf3' and verification_status not in ('verified_against_standard','corrected');
