-- A_b_a
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $A_{\mathrm{b}, \mathrm{a}}$ & ha & angeschlossene befestigte Fläche (in Bezug auf Regenwasserabfluss) | Der Anwendungsbereich dieser RBF beschränkt sich auf innerörtliche Verkehrsflächen (Straßen, Wege, Plätze) mit einer befestigten, angeschlossenen Fläche von $A_{\mathrm{b}, \mathrm{a}}<1$ ha. — printed p.12 and p.33', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.2, printed p.12 and p.33) [VC]', verified_at=now() where id='a177e367-ffbc-46e6-a0f5-d432759d5f88' and verification_status not in ('verified_against_standard','corrected');
-- A_F
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $A_{\text {F }}$ & $\mathrm{m}^{2}$ & Bodenfilteroberfläche, gemessen auf der Oberkante des Filterkörpers | Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden. — printed p.12 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.12 and p.37) [VC]', verified_at=now() where id='1ff5c6bd-bd74-4ec1-8b3f-3c8bc8531e18' and verification_status not in ('verified_against_standard','corrected');
