-- b_krit
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $b_{\text {krit }}$ & $\mathrm{kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ & zulässige spezifische jährliche Filterflächenbelastung mit AFS63 | Mit entsprechender Nachweisführung [...] (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ [...] möglich. — printed p.12 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.12 and p.37) [VC]; note: value 7 kg/(m²·a) is inherited from DWA-A 178:2019; stored as an editable number (STAGED S-6)', verified_at=now() where id='b686518f-ddf0-45ca-9b64-fca14a301b9d' and verification_status not in ('verified_against_standard','corrected');
-- b_R_a
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $b_{\mathrm{R}, \mathrm{a}}$ & kg/(ha•a) & mittlere spezifische AFS63-Jahresfrachtpotenziale des Regenwasserabflusses bezogen auf die Einzugsgebietsfläche $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ | Mit entsprechender Nachweisführung [...] (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ [...] möglich. — printed p.12 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.12 and p.37) [VC]; note: Tab. 2 refers to "A_E,b,a", a symbol Tab. 2 itself does not define (source/transcript quirk)', verified_at=now() where id='19aa5111-1bba-4b6f-b0ad-9d7e1fa68daa' and verification_status not in ('verified_against_standard','corrected');
-- h_RBF
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $h_{\text {RBF }}$ & m & Einbautiefe eines Retentionsbodenfilterbecken | In Bild 8 sind die aufgeführten vertikalen Mindestmaße und Proportionen beispielhaft für einen Filterkörper mit Deckschicht dargestellt. Mit diesem Aufbau sind Klein-RBF mit einer Einbautiefe von lediglich $h_{\text {RBF }} \geqslant 0,6 \mathrm{~m}$ möglich, was insbesondere bei flacher Topografie, geringen Gefälleverhältnissen und/oder geringer Tiefenverfügbarkeit vorteilhaft ist. — printed p.13 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.3.2.2, printed p.13 and p.37) [VC]; note: "≥ 0,6 m möglich" describes the achievable minimum depth of the Bild 8 build-up, not a requirement — gate REQ-06 treats it as a floor (STAGED S-3)', verified_at=now() where id='bcc09b2b-98e8-47ff-b034-55d05bde21a9' and verification_status not in ('verified_against_standard','corrected');
-- A_F_anteil_Aba
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden. — printed p.37', verification_note='md-verified 2026-09-05 (§5.5.4, printed p.37) [VC]; note: A_F < 1,0 % is allowed with the b_krit Nachweis (next paragraph) — gate REQ-06 pins == 1.0 (STAGED S-3)', verified_at=now() where id='d5a9b17d-4496-4b28-a456-115f90109209' and verification_status not in ('verified_against_standard','corrected');
-- eta_AFS63
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Im Merkblatt verwendete Abkürzungen und Formelzeichen | $\eta_{\text {AFS } 63}$ & \% & mittlerer jährlicher hydraulischer Wirkungsgrad des Rückhalts an abfiltrierbaren Stoffen mit Korngrößen von $0,45 \mu \mathrm{~m}$ bis $63 \mu \mathrm{~m}$ (Feinanteil) | Mit dieser Anlagenkonfiguration können bei einer nutzbaren Einstauhöhe von $h_{\mathrm{RR}} \geqslant 0,2 \mathrm{~m}$ und einer Drosselung über den Fließwiderstand des Filtermaterials > $85 \%$ der zufließenden mittleren Jahreswassermenge mit einem AFS63-Wirkungsgrad von $\eta_{\mathrm{AFS} 63} \geqslant 95 \%$ behandelt werden. — printed p.13 and p.37', verification_note='md-verified 2026-09-05 (§3.2 / §5.5.4, printed p.13 and p.37) [VC]; note: an outcome of the standard configuration ("können ... behandelt werden"), not an engineer input', verified_at=now() where id='fde81f97-46f1-4338-8f2c-20d81c37fb5f' and verification_status not in ('verified_against_standard','corrected');

